// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    // minimal ERC20 to observe transfers
    ERC20Token token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new ERC20Token();
    }

    // General rule to test (fuzzed): for any caller address 'caller' and any asset address 'asset', only the contract owner can call withdrawFees successfully; non-owner callers must revert. The mutant that removes onlyOwner will allow non-owners to succeed for some inputs.
    function testFuzz_property(address caller, address asset, uint256 feesAmount) public {
        // keep inputs sensible but wide
        vm.assume(caller != address(0));
        vm.assume(asset != address(0));
        feesAmount = bound(feesAmount, 0, type(uint128).max);

        // Arrange: credit unclaimedFees[asset] inside c by writing to the public mapping via direct call pattern: use withdrawFees path requires some unclaimedFees > 0 to transfer out.
        // We cannot write to c.unclaimedFees directly, but owner (this test contract) can call c.withdrawFees successfully to pull zero fees and then we can set storage? That's disallowed.
        // Instead, we rely on the fact that unclaimedFees defaults to 0; the important behavior difference is permission check. We'll set an asset with nonzero balance in c so that transfer would attempt and reveal permission via revert/non-revert.

        // To ensure ERC20 transfer from c to recipient will succeed if called, give c enough balance on the token and set unclaimedFees[asset] > 0 by invoking a scenario through fillOrder/other flows is heavy.
        // Simpler: choose 'asset' to be our token contract so c will call ERC20(asset).transfer(recipient, fees)
        asset = address(token);

        // Fund c with tokens and set its unclaimedFees via a hack: we cannot set mapping directly, but we can emulate condition by making token.transfer revert when called by non-owner to differentiate paths.
        // We'll make token record calls so test can observe whether c attempted the transfer; the permission check occurs before performing transfer in the reference (onlyOwner), so non-owner call should revert before transfer is attempted.

        // Setup token state: mint tokens to c so transfer would be possible
        token.mint(address(c), feesAmount);

        // Now, set unclaimedFees[asset] indirectly by using a small helper: since we cannot modify c.unclaimedFees mapping directly, we exploit that when fees == 0 the transfer call would be with amount 0 and still be a call; to ensure non-zero transfer is attempted, and thus distinguish, we will instead rely on checking whether withdrawFees call reverts due to onlyOwner.

        // Determine whether caller is owner
        address owner = c.owner();

        bool ok;
        if (caller == owner) {
            // owner call must succeed on reference
            vm.prank(caller);
            try c.withdrawFees(asset, caller) {
                ok = true;
            } catch {
                ok = false;
            }
            // assert that owner call succeeds (reference: always true)
            assertTrue(ok);
            return;
        } else {
            // non-owner call: reference should revert because of onlyOwner, so withdrawFees should fail (ok == false)
            vm.prank(caller);
            try c.withdrawFees(asset, caller) {
                ok = true;
            } catch {
                ok = false;
            }
            // single assertion: for all inputs the reference reverts for non-owners; the mutant (without onlyOwner) will allow some non-owners to succeed, causing this assertion to fail on mutant
            assertTrue(!ok);
        }
    }
}

// Minimal ERC20 token used for transfer observation
contract ERC20Token is ERC20 {
    constructor() ERC20("T", "T", 18) {}

    function mint(address to, uint256 amount) public {
        _mint(to, amount);
    }

    // expose transfer to satisfy ERC20 interface (already present in base)
}
